<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Registration\Infrastructure\Driven;

use Override;
use PDO;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Security\AesCypherService;
use Civi\Lughauth\Features\Oidc\Registration\Domain\ClientRegistrationData;
use Civi\Lughauth\Features\Oidc\Registration\Domain\ClientRegistrationRequest;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Gateway\ClientRegistrationGateway;

final class ClientRegistrationSqlAdapter implements ClientRegistrationGateway
{
    public function __construct(
        private readonly PDO $pdo,
        private readonly AesCypherService $cypher,
    ) {
    }

    #[Override]
    public function create(
        string $clientId,
        string $clientSecret,
        string $registrationAccessToken,
        ClientRegistrationRequest $request,
    ): array {
        $encryptedSecret = 'cyphered://' . $this->cypher->encryptForAll($clientSecret);
        $tokenHash = hash('sha256', $registrationAccessToken);
        $now = new \DateTimeImmutable();
        $nowStr = $now->format('Y-m-d H:i:s');

        $stmt = $this->pdo->prepare(
            'INSERT INTO access_trusted_client (
                uid, version, code, allow_all_scopes, public_allow, secret_oauth, enabled,
                registration_access_token_hash, client_name, logo_uri, client_uri, policy_uri, tos_uri,
                token_endpoint_auth_method, grant_types_json, response_types_json,
                back_channel_logout_uri, front_channel_logout_uri,
                back_channel_logout_session_required, front_channel_logout_session_required,
                dynamically_registered, registered_at
            ) VALUES (
                :uid, 0, :code, 0, 1, :secret_oauth, 1,
                :rat_hash, :client_name, :logo_uri, :client_uri, :policy_uri, :tos_uri,
                :auth_method, :grant_types, :response_types,
                :bc_logout_uri, :fc_logout_uri,
                0, 0,
                1, :registered_at
            )'
        );

        $stmt->bindValue('uid', $clientId, PDO::PARAM_STR);
        $stmt->bindValue('code', $clientId, PDO::PARAM_STR);
        $stmt->bindValue('secret_oauth', $encryptedSecret, PDO::PARAM_STR);
        $stmt->bindValue('rat_hash', $tokenHash, PDO::PARAM_STR);
        $stmt->bindValue('client_name', $request->clientName, PDO::PARAM_STR);
        $stmt->bindValue('logo_uri', $request->logoUri, PDO::PARAM_STR);
        $stmt->bindValue('client_uri', $request->clientUri, PDO::PARAM_STR);
        $stmt->bindValue('policy_uri', $request->policyUri, PDO::PARAM_STR);
        $stmt->bindValue('tos_uri', $request->tosUri, PDO::PARAM_STR);
        $stmt->bindValue('auth_method', $request->tokenEndpointAuthMethod, PDO::PARAM_STR);
        $stmt->bindValue('grant_types', json_encode($request->grantTypes), PDO::PARAM_STR);
        $stmt->bindValue('response_types', json_encode($request->responseTypes), PDO::PARAM_STR);
        $stmt->bindValue('bc_logout_uri', $request->backchannelLogoutUri, PDO::PARAM_STR);
        $stmt->bindValue('fc_logout_uri', $request->frontchannelLogoutUri, PDO::PARAM_STR);
        $stmt->bindValue('registered_at', $nowStr, PDO::PARAM_STR);
        $stmt->execute();

        $this->insertRedirectUris($clientId, $request->redirectUris);

        return [
            'clientId' => $clientId,
            'issuedAt' => $now->getTimestamp(),
        ];
    }

    #[Override]
    public function findByClientIdAndToken(string $clientId, string $registrationAccessToken): ?ClientRegistrationData
    {
        $tokenHash = hash('sha256', $registrationAccessToken);

        $stmt = $this->pdo->prepare(
            'SELECT c.*, GROUP_CONCAT(r.url) as redirect_uris_concat
             FROM access_trusted_client c
             LEFT JOIN access_trusted_client_allowed_redirect r ON r.client = c.uid
             WHERE c.uid = :uid AND c.registration_access_token_hash = :rat_hash
               AND c.dynamically_registered = 1
             GROUP BY c.uid'
        );
        $stmt->bindValue('uid', $clientId, PDO::PARAM_STR);
        $stmt->bindValue('rat_hash', $tokenHash, PDO::PARAM_STR);
        $stmt->execute();

        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($row === false) {
            return null;
        }

        return $this->mapRow($row, '');
    }

    #[Override]
    public function update(string $clientId, string $registrationAccessToken, ClientRegistrationRequest $request): ?ClientRegistrationData
    {
        $tokenHash = hash('sha256', $registrationAccessToken);

        $stmt = $this->pdo->prepare(
            'UPDATE access_trusted_client SET
                client_name = :client_name,
                logo_uri = :logo_uri,
                client_uri = :client_uri,
                policy_uri = :policy_uri,
                tos_uri = :tos_uri,
                token_endpoint_auth_method = :auth_method,
                grant_types_json = :grant_types,
                response_types_json = :response_types,
                back_channel_logout_uri = :bc_logout_uri,
                front_channel_logout_uri = :fc_logout_uri
             WHERE uid = :uid AND registration_access_token_hash = :rat_hash AND dynamically_registered = 1'
        );
        $stmt->bindValue('uid', $clientId, PDO::PARAM_STR);
        $stmt->bindValue('rat_hash', $tokenHash, PDO::PARAM_STR);
        $stmt->bindValue('client_name', $request->clientName, PDO::PARAM_STR);
        $stmt->bindValue('logo_uri', $request->logoUri, PDO::PARAM_STR);
        $stmt->bindValue('client_uri', $request->clientUri, PDO::PARAM_STR);
        $stmt->bindValue('policy_uri', $request->policyUri, PDO::PARAM_STR);
        $stmt->bindValue('tos_uri', $request->tosUri, PDO::PARAM_STR);
        $stmt->bindValue('auth_method', $request->tokenEndpointAuthMethod, PDO::PARAM_STR);
        $stmt->bindValue('grant_types', json_encode($request->grantTypes), PDO::PARAM_STR);
        $stmt->bindValue('response_types', json_encode($request->responseTypes), PDO::PARAM_STR);
        $stmt->bindValue('bc_logout_uri', $request->backchannelLogoutUri, PDO::PARAM_STR);
        $stmt->bindValue('fc_logout_uri', $request->frontchannelLogoutUri, PDO::PARAM_STR);
        $stmt->execute();

        if ($stmt->rowCount() === 0) {
            return null;
        }

        $this->replaceRedirectUris($clientId, $request->redirectUris);

        return $this->findByClientIdAndToken($clientId, $registrationAccessToken);
    }

    #[Override]
    public function delete(string $clientId, string $registrationAccessToken): bool
    {
        $tokenHash = hash('sha256', $registrationAccessToken);

        $checkStmt = $this->pdo->prepare(
            'SELECT uid FROM access_trusted_client
             WHERE uid = :uid AND registration_access_token_hash = :rat_hash AND dynamically_registered = 1'
        );
        $checkStmt->bindValue('uid', $clientId, PDO::PARAM_STR);
        $checkStmt->bindValue('rat_hash', $tokenHash, PDO::PARAM_STR);
        $checkStmt->execute();

        if ($checkStmt->fetch(PDO::FETCH_ASSOC) === false) {
            return false;
        }

        $delRedirects = $this->pdo->prepare('DELETE FROM access_trusted_client_allowed_redirect WHERE client = :uid');
        $delRedirects->bindValue('uid', $clientId, PDO::PARAM_STR);
        $delRedirects->execute();

        $delClient = $this->pdo->prepare('DELETE FROM access_trusted_client WHERE uid = :uid');
        $delClient->bindValue('uid', $clientId, PDO::PARAM_STR);
        $delClient->execute();

        return true;
    }

    #[Override]
    public function readRegistrationPolicy(string $tenant): string
    {
        $stmt = $this->pdo->prepare(
            'SELECT tc.dynamic_registration_policy
             FROM access_tenant_config tc
             JOIN access_tenant t ON t.uid = tc.tenant
             WHERE t.name = :tenant_name
             LIMIT 1'
        );
        $stmt->bindValue('tenant_name', $tenant, PDO::PARAM_STR);
        $stmt->execute();

        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if ($row === false) {
            return 'disabled';
        }

        return (string) ($row['dynamic_registration_policy'] ?? 'disabled');
    }

    private function insertRedirectUris(string $clientId, array $uris): void
    {
        foreach ($uris as $uri) {
            $stmt = $this->pdo->prepare(
                'INSERT INTO access_trusted_client_allowed_redirect (uid, version, url, client)
                 VALUES (:uid, 0, :url, :client)'
            );
            $stmt->bindValue('uid', Random::uuid(), PDO::PARAM_STR);
            $stmt->bindValue('url', (string) $uri, PDO::PARAM_STR);
            $stmt->bindValue('client', $clientId, PDO::PARAM_STR);
            $stmt->execute();
        }
    }

    private function replaceRedirectUris(string $clientId, array $uris): void
    {
        $del = $this->pdo->prepare('DELETE FROM access_trusted_client_allowed_redirect WHERE client = :uid');
        $del->bindValue('uid', $clientId, PDO::PARAM_STR);
        $del->execute();

        $this->insertRedirectUris($clientId, $uris);
    }

    private function mapRow(array $row, string $registrationClientUri): ClientRegistrationData
    {
        $redirectUris = [];
        if (!empty($row['redirect_uris_concat'])) {
            $redirectUris = explode(',', (string) $row['redirect_uris_concat']);
        }

        $grantTypes = ['authorization_code'];
        if (!empty($row['grant_types_json'])) {
            $decoded = json_decode((string) $row['grant_types_json'], true);
            if (is_array($decoded)) {
                $grantTypes = $decoded;
            }
        }

        $responseTypes = ['code'];
        if (!empty($row['response_types_json'])) {
            $decoded = json_decode((string) $row['response_types_json'], true);
            if (is_array($decoded)) {
                $responseTypes = $decoded;
            }
        }

        $issuedAt = 0;
        if (!empty($row['registered_at'])) {
            $issuedAt = (new \DateTimeImmutable((string) $row['registered_at']))->getTimestamp();
        }

        return new ClientRegistrationData(
            clientId: (string) $row['uid'],
            redirectUris: $redirectUris,
            grantTypes: $grantTypes,
            responseTypes: $responseTypes,
            scope: null,
            tokenEndpointAuthMethod: (string) ($row['token_endpoint_auth_method'] ?? 'client_secret_basic'),
            clientName: isset($row['client_name']) && $row['client_name'] !== '' ? (string) $row['client_name'] : null,
            logoUri: isset($row['logo_uri']) && $row['logo_uri'] !== '' ? (string) $row['logo_uri'] : null,
            clientUri: isset($row['client_uri']) && $row['client_uri'] !== '' ? (string) $row['client_uri'] : null,
            policyUri: isset($row['policy_uri']) && $row['policy_uri'] !== '' ? (string) $row['policy_uri'] : null,
            tosUri: isset($row['tos_uri']) && $row['tos_uri'] !== '' ? (string) $row['tos_uri'] : null,
            backchannelLogoutUri: isset($row['back_channel_logout_uri']) && $row['back_channel_logout_uri'] !== '' ? (string) $row['back_channel_logout_uri'] : null,
            frontchannelLogoutUri: isset($row['front_channel_logout_uri']) && $row['front_channel_logout_uri'] !== '' ? (string) $row['front_channel_logout_uri'] : null,
            clientIdIssuedAt: $issuedAt,
            registrationClientUri: $registrationClientUri,
        );
    }
}
